SELECT p.*, u.name as authorName, u.company_name as authorCompany, u.role as authorRole FROM post p JOIN user u ON p.user_id = u.user_id WHERE p.is_deleted = false
AND p.title LIKE CONCAT('%', #{keyword}, '%')
AND p.status_id = #{statusId}
AND p.created_at >= #{startDate}
AND p.created_at < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
AND u.name LIKE CONCAT('%', #{authorName}, '%')
ORDER BY p.post_id DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM post p JOIN user u ON p.user_id = u.user_id WHERE p.is_deleted = false
AND p.title LIKE CONCAT('%', #{keyword}, '%')
AND p.status_id = #{statusId}
AND p.created_at >= #{startDate}
AND p.created_at < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
AND u.name LIKE CONCAT('%', #{authorName}, '%')

