UPDATE post
SET status_id = #{statusId},
    title = #{title},
    content = #{content}
WHERE post_id = #{postId}

UPDATE post
SET is_deleted = true
WHERE post_id = #{postId}

UPDATE post
SET view_count = view_count + 1
WHERE post_id = #{postId}
